uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Parameter mappings (Original)
uniform float u_speed;
uniform float u_scale;
uniform float u_intensity;
uniform float u_color_cycle;
uniform float u_layers;

// Parameter mappings (Structure)
uniform float u_density;
uniform float u_connection_radius;
uniform float u_pulse_intensity;

// --- NEW Parameter mappings for Independent Colors ---
uniform float u_color_base;
uniform float u_color_pulse;

out vec4 fragColor;

// --- Helper Functions ---

mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// 1D Hash for random values
float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

// 2D Hash for positions
vec2 hash22(vec2 p) {
    float n = hash21(p);
    return vec2(n, hash21(p + n));
}

// Distance to a line segment
float distLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

// Standard HSV to RGB conversion for smooth color sliding
vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Helper to draw a synapse connection
void addConnection(vec2 f, vec2 p1, vec2 offs, vec2 dir, vec2 id, float t, float coreSharpness, float haloSharpness, float fade, vec3 baseCol, vec3 pulseCol, float connRadius, float pulseInt, inout vec3 layerColor) {
    vec2 offs2 = offs + dir;

    // Get position of the target neighbor node
    vec2 p2 = offs2 + 0.5 + 0.4 * sin(t * 2.0 + hash22(id + offs2) * 6.28);
    float dConn = distance(p1, p2);

    // Check against the customizable connection radius
    if(dConn < connRadius) {
        float dLine = distLine(f, p1, p2);

        // Firing Pulse Logic
        float pulseTime = t * 10.0 + hash21(id + offs) * 20.0;
        float pulse = smoothstep(0.9, 1.0, sin(dConn * 6.0 - pulseTime));

        // Line Rendering with DoF Sharpness
        float lineTotal = exp(-dLine * coreSharpness) + exp(-dLine * haloSharpness) * 0.4;

        // Fade lines out organically based on length and radius
        float connFade = smoothstep(connRadius, connRadius * 0.5, dConn);

        // Accumulate color: Mix the two independent colors
        layerColor += mix(baseCol, pulseCol, pulse * pulseInt) * lineTotal * connFade * fade * (0.5 + pulse * pulseInt);
    }
}

void main() {
    // 1. Correct Aspect Ratio UVs
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;

    // 2. Timing & Parameters (with fallback defaults if faders are at 0)
    float spd = (u_speed <= 0.0) ? 0.2 : u_speed;
    float t = iTime * spd;
    float brightness = (u_intensity <= 0.0) ? 1.5 : u_intensity;
    float scaleBase = (u_scale <= 0.0) ? 1.0 : u_scale;
    float layerCount = (u_layers <= 0.0) ? 5.0 : u_layers;

    float density = (u_density <= 0.0) ? 1.0 : u_density * 2.0; 
    float connRadius = (u_connection_radius <= 0.0) ? 1.5 : u_connection_radius * 2.5;
    float pulseInt = (u_pulse_intensity <= 0.0) ? 1.5 : u_pulse_intensity * 3.0;

    // --- Dynamic Color Generation ---
    // base hue defaults to 0.55 (Cyan). Add user fader and the animated cycle.
    float hueBase = fract(0.55 + u_color_base + (t * u_color_cycle * 0.1));
    // pulse hue defaults to 0.10 (Gold/Orange). Add user fader and animated cycle.
    float huePulse = fract(0.10 + u_color_pulse + (t * u_color_cycle * 0.1));

    // Convert to rich RGB colors
    vec3 baseCol = hsv2rgb(vec3(hueBase, 0.85, 1.0));
    vec3 pulseCol = hsv2rgb(vec3(huePulse, 0.8, 1.0));

    // --- Deep Volumetric Background ---
    // Automatically tint the background void to match the base color
    vec3 bgCenter = baseCol * 0.12; 
    vec3 bgEdge = vec3(0.0, 0.01, 0.02);   // Near Black
    vec3 finalColor = mix(bgCenter, bgEdge, length(uv0) * 1.5);

    // 3. Infinite Zoom & Depth of Field Layer Loop
    for(int i = 0; i < 5; i++) {
        float fi = float(i);
        if(fi >= layerCount) break;

        // Z-depth calculates distance from camera.
        float z = fract(fi * 0.2 + t * 0.1); 

        // Fade layers in at the back (z=1) and out at the camera (z=0)
        float fade = smoothstep(0.0, 0.2, z) * smoothstep(1.0, 0.8, z);

        // Depth of Field Blur
        float blur = smoothstep(0.0, 0.5, abs(z - 0.5)); 

        // Dynamic sharpness based on DoF
        float coreSharpness = mix(60.0, 10.0, blur);
        float haloSharpness = mix(15.0, 3.0, blur);

        // Scale space based on depth AND Density fader
        float size = mix(12.0, 0.5, z) * scaleBase * density;
        vec2 layerUV = uv * size;

        // Parallax rotation per layer
        layerUV *= rot(z * 0.5 + fi);

        // Grid setup for Voronoi-style placement
        vec2 id = floor(layerUV);
        vec2 f = fract(layerUV);

        vec3 layerColor = vec3(0.0);
        float layerNodes = 0.0;

        // Loop through the 3x3 local neighborhood
        for(int y = -1; y <= 1; y++) {
            for(int x = -1; x <= 1; x++) {
                vec2 offs = vec2(float(x), float(y));

                // Position of the node in this specific cell
                vec2 p1 = offs + 0.5 + 0.4 * sin(t * 2.0 + hash22(id + offs) * 6.28);

                // 1. Draw the Node (Cell Body)
                float dNode = length(f - p1);
                layerNodes += exp(-dNode * coreSharpness) + (exp(-dNode * haloSharpness) * 0.5);

                // 2. Draw Connections to neighbors
                addConnection(f, p1, offs, vec2(1.0, 0.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor); // Right
                addConnection(f, p1, offs, vec2(0.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor); // Down
                addConnection(f, p1, offs, vec2(1.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor); // Down-Right
                addConnection(f, p1, offs, vec2(-1.0, 1.0), id, t, coreSharpness, haloSharpness, fade, baseCol, pulseCol, connRadius, pulseInt, layerColor); // Down-Left
            }
        }

        // Add nodes to the layer using a bright white mixed with the base color
        layerColor += mix(baseCol, vec3(1.0), 0.7) * layerNodes * fade;

        finalColor += layerColor * brightness;
    }

    // 4. Post-Processing
    float vig = 1.0 - length(uv0) * 0.7;
    finalColor *= smoothstep(0.0, 1.0, vig);

    // Tone mapping to prevent burning out the bright spots
    finalColor = finalColor / (1.0 + finalColor * 0.2);
    finalColor = pow(finalColor, vec3(0.85));

    fragColor = vec4(finalColor, 1.0);
}
